problems.solution:
function deepClone(value, seen = new WeakMap()) {
  if (value === null || typeof value !== 'object') {
    return typeof value === 'function' ? undefined : value;
  }
  if (seen.has(value)) return seen.get(value);
  if (value instanceof Date) return new Date(value.getTime());
  if (value instanceof RegExp) {
    const re = new RegExp(value.source, value.flags);
    re.lastIndex = value.lastIndex;
    return re;
  }
  if (value instanceof Map) {
    const out = new Map();
    seen.set(value, out);
    value.forEach((v, k) => out.set(deepClone(k, seen), deepClone(v, seen)));
    return out;
  }
  if (value instanceof Set) {
    const out = new Set();
    seen.set(value, out);
    value.forEach((v) => out.add(deepClone(v, seen)));
    return out;
  }
  if (Array.isArray(value)) {
    const out = [];
    seen.set(value, out);
    value.forEach((v, i) => { out[i] = deepClone(v, seen); });
    return out;
  }
  const out = Object.create(Object.getPrototypeOf(value));
  seen.set(value, out);
  for (const key of Object.keys(value)) {
    if (typeof value[key] === 'function') continue;
    out[key] = deepClone(value[key], seen);
  }
  return out;
}

think.q:
A developer caches like this:<pre><code>return function (...args) {
  if (result) return result
  result = fn.apply(this, args)
  return result
}</code></pre>With <code>const f = once(() =&gt; 0)</code>, how many times does the function run after <code>f(); f(); f()</code>?

checks.test:
let n = 0; const f = once(() => { n++; return 0 });
f(); f(); f();
console.log(n); // expected: 1

let n = 0; const f = once((x) => { n++; return x });
f(1); f.reset();
console.log(f(2), n); // expected: 2 2

checks.verify:
