assert(typeof f.reset === 'function', 'reset must exist'); f.reset();
assert(f(2) === 2 && n === 2, 'after reset the next call must run fn again')

problems.solution:
function once(fn) {
  let called = false;
  let result;
  function wrapper(...args) {
    if (!called) {
      called = true;
      result = fn.apply(this, args);
    }
    return result;
  }
  wrapper.reset = function () {
    called = false;
    result = undefined;
  };
  return wrapper;
}

