}

problems.solution:
function assertFn(fn) {
  if (typeof fn !== 'function') throw new TypeError(String(fn) + ' is not a function');
}

function myMap(arr, fn, thisArg) {
  assertFn(fn);
  const out = new Array(arr.length);
  for (let i = 0; i < arr.length; i++) {
    if (i in arr) out[i] = fn.call(thisArg, arr[i], i, arr);
  }
  return out;
}

function myFilter(arr, fn, thisArg) {
  assertFn(fn);
  const out = [];
  for (let i = 0; i < arr.length; i++) {
    if (i in arr && fn.call(thisArg, arr[i], i, arr)) out.push(arr[i]);
  }
  return out;
}

function myReduce(arr, fn) {
  assertFn(fn);
  let i = 0;
  let acc;
  if (arguments.length >= 3) {
    acc = arguments[2];
  } else {
    while (i < arr.length && !(i in arr)) i++;
    if (i >= arr.length) throw new TypeError('Reduce of empty array with no initial value');
    acc = arr[i++];
  }
  for (; i < arr.length; i++) {
    if (i in arr) acc = fn(acc, arr[i], i, arr);
  }
  return acc;
}

