problems.solution:
Function.prototype.myBind = function (thisArg, ...partials) {
  if (typeof this !== 'function') {
    throw new TypeError('Bind must be called on a function');
  }
  const target = this;
  function bound(...args) {
    const allArgs = partials.concat(args);
    if (new.target) {
      return Reflect.construct(target, allArgs);
    }
    return target.apply(thisArg, allArgs);
  }
  return bound;
};
